 /* Resolve a wall-clock time in an IANA zone; reject non-existent DST times. */
 function zoned(date,clock,tz){
  const [y,m,d]=date.split('-').map(Number),[h,min]=clock.split(':').map(Number),desired=Date.UTC(y,m-1,d,h,min);if(!Number.isFinite(desired))throw Error('Choose a valid date and time.');
  const format=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}),parts=t=>Object.fromEntries(format.formatToParts(new Date(t)).map(p=>[p.type,p.value]));let guess=desired;
  for(let i=0;i<3;i++){const p=parts(guess),local=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);guess+=desired-local;}const p=parts(guess);
  if(+p.year!==y||+p.month!==m||+p.day!==d||+p.hour!==h||+p.minute!==min)throw Error('This local time is unavailable during a clock change. Choose another time.');return new Date(guess).toISOString();
 }
